import { jsx as _jsx } from "react/jsx-runtime";
import { describe, it, expect, vi, beforeAll, afterAll } from "vitest";
import { screen, render, within } from "@testing-library/react";
import { userEvent } from "@testing-library/user-event";
import dayjs from "dayjs";
import { RDSConfigProvider } from "../../../rdsConfigProvider";
import TabbedDateRangePicker from "../TabbedDateRangePicker";
import { parseTimeFrame } from "../util/parseTimeFrame";
describe("<TabbedDateRangePicker /> time frame tab", () => {
    const presets = [
        {
            label: "Last 20 minutes",
            onParse: (now) => ({
                from: now.subtract(20, "minute").valueOf(),
                timeFrame: "Last 20 minutes",
                to: now.valueOf(),
            }),
        },
        {
            label: "Last 1 hour",
            onParse: (now) => ({
                from: now.subtract(1, "hour").valueOf(),
                timeFrame: "Last 1 hour",
                to: now.valueOf(),
            }),
        },
        {
            label: "Yesterday",
            onParse: (now) => ({
                from: now.startOf("day").subtract(1, "day").valueOf(),
                timeFrame: "Yesterday",
                to: now.startOf("day").subtract(1, "day").endOf("day").valueOf(),
            }),
        },
        {
            label: "Today",
            onParse: (now) => ({
                from: now.startOf("day").valueOf(),
                timeFrame: "Today",
                to: now.valueOf(),
            }),
        },
        {
            label: "Last 1 week",
            onParse: (now) => ({
                from: now.startOf("day").subtract(1, "week").valueOf(),
                timeFrame: "Last 1 week",
                to: now.valueOf(),
            }),
        },
        {
            label: "Last 30 days",
            onParse: (now) => ({
                from: now.subtract(30, "day").valueOf(),
                timeFrame: "Last 30 days",
                to: now.valueOf(),
            }),
        },
    ];
    beforeAll(() => {
        vi.useFakeTimers();
        vi.setSystemTime(dayjs("1 January 2025").startOf("day").toDate());
    });
    afterAll(() => {
        vi.useRealTimers();
    });
    it("deselects the selected preset when the custom preset unit is updated", async () => {
        // Setup fixture
        const user = userEvent.setup({ advanceTimers: vi.advanceTimersByTime });
        // Exercise SUT
        render(_jsx(RDSConfigProvider, { children: _jsx(TabbedDateRangePicker, { onChange: vi.fn(), presets: [{ presets }], tabs: ["preset"], value: undefined }) }));
        // Exercise SUT
        await user.click(screen.getByPlaceholderText("Date Range"));
        await user.click(screen.getByLabelText("Unit of time"));
        await user.click(document.querySelectorAll(".MuiMenuItem-root")[1]);
        // Verify results
        expect(screen.queryByTestId("selected-preset")).not.toBeInTheDocument();
    });
    it("prevents submission of a custom date range that is larger the provided maximum range", async () => {
        // Setup fixture
        const user = userEvent.setup({ advanceTimers: vi.advanceTimersByTime });
        render(_jsx(RDSConfigProvider, { children: _jsx(TabbedDateRangePicker, { maxCustomRange: { number: 1, unit: "day" }, onChange: vi.fn(), onParse: parseTimeFrame, presets: [{ presets }], tabs: ["preset"], value: undefined }) }));
        // Exercise SUT
        await user.click(screen.getByPlaceholderText("Date Range"));
        await user.type(screen.getByPlaceholderText("#"), "25");
        await user.click(screen.getByLabelText("Unit of time"));
        await user.click(within(document.querySelector(".MuiMenu-list")).getByText("Hours"));
        // Verify results
        expect(screen.getByText("Ok").getAttribute("disabled")).not.toBeNull();
        expect(screen.getByText("Time frame must be less than 1 day")).toBeInTheDocument();
    });
    it("allows submission of a custom date range that is equal to provided maximum range when using different units", async () => {
        // Setup fixture
        const user = userEvent.setup({ advanceTimers: vi.advanceTimersByTime });
        render(_jsx(RDSConfigProvider, { children: _jsx(TabbedDateRangePicker, { maxCustomRange: { number: 1, unit: "day" }, onChange: vi.fn(), onParse: parseTimeFrame, presets: [{ presets }], tabs: ["preset"], timezone: "Europe/Bucharest", value: undefined }) }));
        // Exercise SUT
        await user.click(screen.getByPlaceholderText("Date Range"));
        await user.type(screen.getByPlaceholderText("#"), "24");
        await user.click(screen.getByLabelText("Unit of time"));
        await user.click(within(document.querySelector(".MuiMenu-list")).getByText("Hours"));
        // Verify results
        expect(screen.getByText("Ok").getAttribute("disabled")).toBeNull();
        expect(screen.queryByText("Time frame must be less than 1 day")).not.toBeInTheDocument();
    });
    it("recalculates the 'to' and 'from' values for a time frame that is submitted without a change", async () => {
        // Setup fixture
        const now = dayjs("1 January 2025").startOf("day");
        const onChangeSpy = vi.fn();
        const user = userEvent.setup({ advanceTimers: vi.advanceTimersByTime });
        render(_jsx(RDSConfigProvider, { children: _jsx(TabbedDateRangePicker, { onChange: onChangeSpy, presets: [{ presets }], tabs: ["preset"], value: { timeFrame: presets[0].label } }) }));
        // Exercise SUT
        await user.click(screen.getByPlaceholderText("Date Range"));
        await user.click(screen.getByText("Ok"));
        // Verify behaviour
        expect(onChangeSpy).toHaveBeenNthCalledWith(1, {
            from: now.subtract(20, "minute").valueOf(),
            timeFrame: "Last 20 minutes",
            to: now.valueOf(),
        });
    });
});
